import {BaseEntity} from '../../../shared/domain/model/base-entity';

export type ForecastMethod = 'MACHINE_LEARNING' | 'BASELINE';
export type WeatherCondition = 'SUNNY' | 'CLOUDY' | 'DRIZZLE' | 'RAIN';

/** One day of the forecast: total units, the dish with most units and the detail per dish. */
export interface ForecastDay {
  date: string;
  dayLabel: string;
  dishName: string;
  projectedUnits: number;
  tempMaxC: number;
  precipitationMm: number;
  dishes: {dishName: string; projectedUnits: number}[];
}

/**
 * Projected units per dish for the next days, generated by the ONNX model of the API from the sales
 * history, the Peruvian calendar and the weather forecast (Open-Meteo).
 * @author DataBit
 */
export class DemandForecast implements BaseEntity {
  #id: number;
  #generatedAt: Date;
  #confidenceScore: number;
  #weatherCondition: WeatherCondition;
  #weatherSource: string;
  #method: ForecastMethod;
  #modelVersion: string;
  #days: ForecastDay[];

  constructor(forecast: {id?: number; generatedAt?: Date; confidenceScore?: number; weatherCondition?: WeatherCondition; weatherSource?: string;
    method?: ForecastMethod; modelVersion?: string; days?: ForecastDay[]}) {
    this.#id = forecast.id ?? 0;
    this.#generatedAt = forecast.generatedAt ?? new Date();
    this.#confidenceScore = forecast.confidenceScore ?? 0;
    this.#weatherCondition = forecast.weatherCondition ?? 'SUNNY';
    this.#weatherSource = forecast.weatherSource ?? 'climatology';
    this.#method = forecast.method ?? 'BASELINE';
    this.#modelVersion = forecast.modelVersion ?? '';
    this.#days = forecast.days ?? [];
  }

  get id(): number { return this.#id; }
  get generatedAt(): Date { return this.#generatedAt; }
  get confidenceScore(): number { return this.#confidenceScore; }
  get weatherCondition(): WeatherCondition { return this.#weatherCondition; }
  get weatherSource(): string { return this.#weatherSource; }
  get method(): ForecastMethod { return this.#method; }
  get modelVersion(): string { return this.#modelVersion; }
  get days(): ForecastDay[] { return this.#days; }

  get totalUnits(): number {
    return this.#days.reduce((total, day) => total + day.projectedUnits, 0);
  }

  /** Largest day total, used to scale the bar chart. */
  get maxDailyUnits(): number {
    return Math.max(1, ...this.#days.map(day => day.projectedUnits));
  }

  get confidencePercent(): number {
    return Math.round(this.#confidenceScore * 100);
  }
}
